    INSERT INTO [stg].[Source] ([SourceCode], [SourceTitle], [URL], [DetailsUsed], [DateReviewed]) VALUES
        (N'SRC-MOS-CODEHUB', N'Code Hub Mostar – official meeting-room price list', N'https://code-hub.eu/wp-content/uploads/2025/04/Price-list-2025-Meeting-Rooms_Code-Hub-Mostar.pdf', N'Westeros (2), Hogwarts (8), Middle-Earth (10); Code Hub Mostar meeting rooms. Open Space name is supported by the official Intera/Code Hub pages.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-MOS-MEPAS', N'Hotel Mepas – Kongresni centar', N'https://mepas-hotel.ba/kongresni-centar/', N'Queen (up to 700), Princess (up to 200), Lady (up to 22); official venue address is on Hotel Mepas contact page.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-MOS-INTERA', N'INTERA – Business incubator', N'https://intera.ba/en/business-incubator/', N'Confirms offices, conference rooms, and presentation rooms at INTERA Technology Park; individual room names and capacities are not stated.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-MOS-OLDTOWN', N'Old Town Nest – official site and public address listings', N'https://oldtownnest.com/ | https://www.google.com/maps/search/?api=1&query=Old+Town+Nest+Mostar', N'Official site confirms a coworking area and work desks in accommodation units. Google Maps lists Kapetanovina 1; several accommodation listings show Kapetanovina 2, so confirm the address with the venue before operational use. Capacity and separate hourly booking are not stated.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-SAR-MOTIFF', N'Motiff Coworking – meetings and events', N'https://www.coworking.motiff.io/', N'Conference room for 8, event space up to 40, day access to coworking; address Valtera Perića 20.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-SAR-SKRIPTA', N'SKRIPTA IdeaLab – space rental', N'https://www.skripta.ba/prostor', N'Space for meetings, training, workshops and team days; 100 m²; address Emerika Bluma 9. Capacity is not published.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-SAR-TERSHOUSE', N'tershouse Roof Gardens – official space page', N'https://www.tershouse.ba/roofgardens', N'Coworking area (286 m²), two conference rooms (120 m² each; capacity 40 each), outdoor amphitheater; Kolodvorska 12.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-SAR-MIKROHUB', N'Mikrohub – official coworking page', N'https://mikrohub.ba/', N'Confirms day-pass workspace, fixed desks and meeting-room use; address Alipašina 2. Individual capacity is not stated.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-BL-QUOROOM', N'Quo Room – official coworking page', N'https://quoroom.co/', N'Confirms Open Space (73 m²), Private Zoom Room, and rentable meeting/training room. Capacity omitted because the page gives 13 and 15 in different sections.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-BL-SPACE', N'S:PACE – official space and contact pages', N'https://space-bl.com/sadrzaj/ | https://space-bl.com/contact/', N'Confirms working area, conference room, and two silent rooms; address Bulevar vojvode Stepe Stepanovića 171E.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-BL-KODEPUNKT', N'Kodepunkt – official coworking page', N'https://kodepunkt.com/', N'Confirms hot desks, three meeting rooms, tutorial room, private office for four; address Milana Karanovića 55. Numbered meeting-room labels are local identifiers because individual names are not listed.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-TZ-BIT', N'BIT Centar – official site', N'https://www.bitcentar.com/', N'Confirms Code Hub coworking, offices, meeting and conference rooms, and Tuzla location at Trg slobode 16.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-TZ-CODEHUB', N'Code Hub Tuzla – public venue listing', N'https://zoyya.com/hr/code-hub-tuzla', N'Lists a work room (9), training room (12), meeting room (12), and event room (42); capacity data is from this venue listing, not the BIT Centar official site.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-CAL-UNSA', N'UNSA – academic calendar 2024/2025', N'https://unsa.ba/sites/default/files/dodatak/2024-07/Akademski%20kalendar%20za%202024-2025.%20godinu.pdf', N'Used only to define plausible exam-period windows for the synthetic work-space scenario; the calendar contains January/February, April, June/July, and August/September exam periods.', CONVERT(date, N'2026-11-14', 23)),
        (N'SRC-CAL-UNTZ', N'University of Tuzla – academic calendar 2024/2025', N'https://untz.ba/wp-content/uploads/2024/09/Odluka_o_kalendaru_organizacije_i_realizacije_nastave_i_ispita_na_prvom_integriranom_prvom_i_drugom_drugom_i_trecem_ciklusu_studija_2024_25_11_09_2024.pdf', N'Used only to define plausible exam-period windows for the synthetic work-space scenario; dates differ from other institutions.', CONVERT(date, N'2026-11-14', 23)),
